const s=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],o=/^(\d{4})-(\d{2})-(\d{2})$/;function u(a,c){const n=o.exec(String(a||"")),e=o.exec(String(c||""));if(!n||!e)return null;const r=t=>Date.UTC(+t[1],+t[2]-1,+t[3]);return Math.round((r(e)-r(n))/864e5)}function i(a,c){const n=o.exec(String(a||""));if(!n)return"";const e=u(a,c);if(e===0)return"today";if(e===1)return"yesterday";const r=`${+n[3]} ${s[+n[2]-1]}`,t=o.exec(String(c||""));return t&&t[1]!==n[1]?`${r} ${n[1]}`:r}function d(a,c,n,e){const r=u(a,c);if(r==null||r<=1)return`over ${e} ${Number(e)===1?"day":"days"}`;const t=i(c,n);return t==="today"?"today":`since ${t}`}export{i as d,d as s};
